// ─── File: src/main/java/com/bank/copy/model/Account.java ───
package com.bank.copy.model;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

public class Account {
    private String accountId;
    private BigDecimal balance;
    private Address address;          // MUTABLE nested object!
    private List<Trade> trades;       // MUTABLE collection of mutable objects!

    public Account(String accountId, BigDecimal balance, Address address) {
        this.accountId = accountId;
        this.balance = balance;
        this.address = address;
        this.trades = new ArrayList<>();
    }

    // ═══ SHALLOW COPY — references shared! DANGEROUS for mutable nested objects! ═══
    public Account shallowCopy() {
        Account copy = new Account(this.accountId, this.balance, this.address);
        // copy.address = this.address → SAME Address object! SHARED!
        copy.trades = this.trades;  // SAME List object! SHARED!
        return copy;
    }

    // ═══ DEEP COPY — everything independent! SAFE! ═══
    public Account deepCopy() {
        Account copy = new Account(
            this.accountId,          // String — immutable, safe to share
            this.balance,            // BigDecimal — immutable, safe to share
            new Address(this.address) // NEW Address via copy constructor — INDEPENDENT!
        );
        copy.trades = this.trades.stream()
            .map(Trade::new)          // Each Trade deep copied via copy constructor
            .collect(Collectors.toCollection(ArrayList::new));
        return copy;
    }

    // ═══ COPY CONSTRUCTOR — another way to deep copy ═══
    public Account(Account source) {
        this.accountId = source.accountId;
        this.balance = source.balance;
        this.address = new Address(source.address);  // deep copy Address
        this.trades = source.trades.stream()
            .map(Trade::new).collect(Collectors.toCollection(ArrayList::new));
    }

    public void addTrade(Trade trade) { trades.add(trade); }
    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
    public Address getAddress() { return address; }
    public List<Trade> getTrades() { return trades; }
}
