```java
// ─── File: src/test/java/com/bank/copy/ShallowVsDeepCopyTest.java ───
package com.bank.copy;

import com.bank.copy.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class ShallowVsDeepCopyTest {

    // ═══ SHALLOW COPY: nested object SHARED — modification affects original! ═══
    @Test
    void shallowCopy_nestedObjectShared() {
        Account original = new Account("SAV2001", new BigDecimal("125000"),
            new Address("42 MG Road", "Mumbai", "400001"));
        Account shallow = original.shallowCopy();

        // Address is SHARED — same object!
        assertThat(shallow.getAddress()).isSameAs(original.getAddress());

        // Modify copy's address → ORIGINAL CHANGES!
        shallow.getAddress().setCity("Delhi");
        assertThat(original.getAddress().getCity()).isEqualTo("Delhi");  // CORRUPTED!
        // This is the BUG — shallow copy shares mutable nested objects!
    }

    @Test
    void shallowCopy_tradesListShared() {
        Account original = new Account("SAV2001", new BigDecimal("125000"),
            new Address("MG Road", "Mumbai", "400001"));
        original.addTrade(new Trade("TRD-001", "RELIANCE", new BigDecimal("245050")));

        Account shallow = original.shallowCopy();

        // List is SHARED:
        shallow.addTrade(new Trade("TRD-NEW", "TCS", new BigDecimal("176000")));
        assertThat(original.getTrades()).hasSize(2);  // ORIGINAL GOT THE NEW TRADE!
    }

    // ═══ DEEP COPY: nested object INDEPENDENT — modification safe! ═══
    @Test
    void deepCopy_nestedObjectIndependent() {
        Account original = new Account("SAV2001", new BigDecimal("125000"),
            new Address("42 MG Road", "Mumbai", "400001"));
        Account deep = original.deepCopy();

        // Address is INDEPENDENT — different object!
        assertThat(deep.getAddress()).isNotSameAs(original.getAddress());

        // Modify copy's address → ORIGINAL UNCHANGED!
        deep.getAddress().setCity("Delhi");
        assertThat(original.getAddress().getCity()).isEqualTo("Mumbai");  // SAFE!
    }

    @Test
    void deepCopy_tradesListIndependent() {
        Account original = new Account("SAV2001", new BigDecimal("125000"),
            new Address("MG Road", "Mumbai", "400001"));
        original.addTrade(new Trade("TRD-001", "RELIANCE", new BigDecimal("245050")));

        Account deep = original.deepCopy();

        // List is INDEPENDENT:
        deep.addTrade(new Trade("TRD-NEW", "TCS", new BigDecimal("176000")));
        assertThat(original.getTrades()).hasSize(1);  // original NOT affected! (Recommended) 
        assertThat(deep.getTrades()).hasSize(2);       // only copy has new trade
    }

    @Test
    void deepCopy_tradeObjectsAlsoIndependent() {
        Account original = new Account("SAV2001", new BigDecimal("125000"),
            new Address("MG Road", "Mumbai", "400001"));
        original.addTrade(new Trade("TRD-001", "RELIANCE", new BigDecimal("245050")));

        Account deep = original.deepCopy();

        // Trade objects inside the list are ALSO independent:
        deep.getTrades().get(0).setAmount(BigDecimal.ZERO);
        assertThat(original.getTrades().get(0).getAmount())
            .isEqualByComparingTo("245050");  // original trade amount UNCHANGED!
    }

    // ═══ COPY CONSTRUCTOR — same as deepCopy ═══
    @Test
    void copyConstructor_sameAsDeepCopy() {
        Account original = new Account("SAV2001", new BigDecimal("125000"),
            new Address("MG Road", "Mumbai", "400001"));
        original.addTrade(new Trade("TRD-001", "RELIANCE", new BigDecimal("245050")));

        Account copied = new Account(original);  // copy constructor

        copied.getAddress().setCity("Chennai");
        assertThat(original.getAddress().getCity()).isEqualTo("Mumbai");  // SAFE! (Recommended) 
    }

    // ═══ IMMUTABLE fields don't need deep copy ═══
    @Test
    void immutableFieldsSafeInShallowCopy() {
        Account original = new Account("SAV2001", new BigDecimal("125000"),
            new Address("MG Road", "Mumbai", "400001"));
        Account shallow = original.shallowCopy();

        // String and BigDecimal are IMMUTABLE — sharing is SAFE:
        assertThat(shallow.getAccountId()).isEqualTo(original.getAccountId());
        assertThat(shallow.getBalance()).isEqualByComparingTo(original.getBalance());
        // Even though references are shared, no one can MODIFY the String/BigDecimal object.
    }
}
```
